mapper.insert:
insert into country(
	country_no, country_name, country_region,
	country_capital, country_population
)
values(

	#{countryNo}, #{countryName}, #{countryRegion}, 
	#{countryCapital}, #{countryPopulation}
)

mapper.update:
update country 
set country_name = #{countryName}, 
	country_region = #{countryRegion},
	country_capital = #{countryCapital}, 
	country_population = #{countryPopulation}
where country_no = #{countryNo}

mapper.select:
select * from (
	select rownum rn, TMP.* from (
		select * from country 

		where country_no > #{lastCountryNo}

		order by country_no asc
	)TMP
) where rn between 1 and #{size}

with temp_list as (
	select rownum rn, TMP.* from (

		select * from country









		and country_region in


			#{countryRegion}





		and country_name like #{countryName} || '%'



		and instr(country_capital, #{countryCapital}) > 0




				and country_population between 
				#{minCountryPopulation} and #{maxCountryPopulation}



				and country_population >= #{minCountryPopulation}




				and country_population <= #{maxCountryPopulation}







		order by 


			${order},


		country_no asc

		)TMP
	)
	select * from (
		select * from temp_list 


		where rn > (
			select rn from temp_list 
			where country_no=#{lastCountryNo}
		)


	) 


	where rownum <= #{size}
